    "user_preferences": {
      "desired_emotion": "过程虐心(外因驱动)+HE结局",
      "forbidden": ["两人之间的大矛盾", "BE结局", "纯双人世界/故事格局小"]
    }
  },
  "selected_recipe": {
    "x_axis_mode_id": "E28",
    "x_axis_mode_name": "爱上仇人",
    "y_axis_tags": ["双向暗恋", "仙侠修真"],
    "reaction_strength": "↘",
    "tension_stars": 4,
    "forbidden_elements": ["两人之间的重大矛盾冲突", "BE结局", "格局过小只围绕两人"],
    "x_axis_display": "两人分属百年世仇家族，身份注定对立，外界势力不断逼迫他们站队、反目，但两人始终暗恋彼此，在家族大战与天道抉择中最终冲破桎梏",
