chs = a2p1['act_two_part1']['chapters_8_to_13'] + a2p2['act_two_part2']['chapters_14_to_18']
outline = {'act_one': a1['act_one'], 'act_two': {'description': a2p1['act_two_part1']['description'], 'story_synopsis': a2p1['act_two_part1']['story_synopsis'], 'key_chapters': chs, 'turning_point': a2p2['turning_point']}, 'act_three': a3['act_three']}
with open('outline.json','w') as f: json.dump(outline,f,ensure_ascii=False,indent=2)
tc = len(outline['act_one']['key_chapters'])+len(outline['act_two']['key_chapters'])+len(outline['act_three']['key_chapters'])
print('Total chapters:',tc)
cs=set()
for ak in ['act_one','act_two','act_three']:
 for ch in outline[ak]['key_chapters']:
  for sc in ch['scene_sequence']:
   for c in sc['characters_present']: cs.add(c)
print('Chars in outline:',cs)
with open('characters.json','r') as f: ch=json.load(f)
ds=set()
for mc in ch['main_characters']: ds.add(mc['name'])
for sc in ch['supporting_characters']: ds.add(sc['name'])
print('Designed:',ds)
print('Missing:',ds-cs)
""}

